-- NearMe Library migration 0015: every library sits in a State -> District -> City (-> optional Area).
--
-- WHY: owners and students pick a state, then see all of its districts, then all towns of that district. Before this,
-- cities were a short hand-typed list with no state or district.
--
-- DATA: the government's Local Government Directory (LGD), via https://github.com/ramSeraph/opendata (lgd-latest).
-- States, districts, and every town that has a municipal body. Generated by scripts/places/build.mjs from
-- scripts/places/0015.template.sql; hand-checked fixes are in scripts/places/overrides.mjs. Do not edit the data by hand.
--
-- EXISTING ROWS: the cities already here keep their ids, so their areas and libraries are untouched. Each library gets
-- the state and district of its city. Area becomes optional: most towns have no areas listed yet.
--
-- A town can span two districts (e.g. Imphal: Imphal West and Imphal East), so towns and districts are linked through
-- city_districts, and a library records which district it is in.

-- ---------------------------------------------------------------- tables
create table public.states (
  id                 uuid primary key default gen_random_uuid(),
  code               text not null unique,     -- 'S9' = LGD state code 9
  name               text not null unique,
  is_union_territory boolean not null default false
);

create table public.districts (
  id        uuid primary key default gen_random_uuid(),
  code      text not null unique,              -- 'D162' = LGD district code 162
  state_id  uuid not null references public.states (id),
  name      text not null,
  unique (id, state_id)                        -- lets a library prove its district is in its state
);
create index districts_state_idx on public.districts (state_id, name);

alter table public.cities
  add column code     text unique,             -- 'C249234' = LGD local body code; null for towns an admin adds
  add column state_id uuid references public.states (id);

create table public.city_districts (
  city_id     uuid not null references public.cities (id),
  district_id uuid not null references public.districts (id),
  primary key (city_id, district_id)           -- lets a library prove its city is in its district
);
create index city_districts_district_idx on public.city_districts (district_id);

