create temporary table place_import_towns (code text primary key, name text not null, state_code text not null, district_codes text[] not null) on commit drop;

create temporary table place_import_live (live_name text primary key, code text not null) on commit drop;


-- ---------------------------------------------------------------- towns
-- Existing cities first, so they keep their ids.
update public.cities c set code = l.code from place_import_live l where lower(c.name) = l.live_name and c.code is null;

do $$
declare unknown text;
begin
  select string_agg(name, ', ' order by name) into unknown from public.cities where code is null;
  if unknown is not null then
    raise exception 'Migration 0015 does not know which official town these cities are: %. Add them to LIVE_CITIES in scripts/places/overrides.mjs and generate again.', unknown;
  end if;
end;
$$;

-- Town names repeat across states (Aurangabad is in Bihar and Maharashtra), so a name is unique per state, not overall.
drop index public.cities_name_unique;

update public.cities c set name = t.name, state_id = s.id
from place_import_towns t join public.states s on s.code = t.state_code
where c.code = t.code;

select t.code, t.name, s.id
from place_import_towns t join public.states s on s.code = t.state_code
where not exists (select 1 from public.cities c where c.code = t.code);

select c.id, d.id
from place_import_towns t
join public.cities c on c.code = t.code
cross join lateral unnest(t.district_codes) as dc(code)
join public.districts d on d.code = dc.code;

alter table public.cities alter column state_id set not null;
create unique index cities_state_name_unique on public.cities (state_id, lower(name));

-- Every town must be reachable from a district, or nobody could ever pick it.
do $$
declare orphan text;
begin
  select string_agg(c.name, ', ') into orphan from public.cities c
  where not exists (select 1 from public.city_districts cd where cd.city_id = c.id);
  if orphan is not null then raise exception 'Migration 0015: towns without a district: %', orphan; end if;
end;
$$;

-- ---------------------------------------------------------------- libraries
alter table public.libraries
  add column state_id    uuid,
  add column district_id uuid;

-- A library takes its city's district. For a city in several districts the first by name is used; the owner can change it.
update public.libraries l
   set district_id = pick.district_id, state_id = pick.state_id
  from (
    select distinct on (cd.city_id) cd.city_id, d.id as district_id, d.state_id
      from public.city_districts cd join public.districts d on d.id = cd.district_id
     order by cd.city_id, d.name
  ) pick
 where pick.city_id = l.city_id;

do $$
begin
  if exists (select 1 from public.libraries where district_id is null) then
    raise exception 'Migration 0015: some libraries could not be given a district.';
  end if;
end;
$$;

alter table public.libraries
  alter column state_id set not null,
  alter column district_id set not null,
  alter column area_id drop not null,          -- the (area_id, city_id) rule from 0001 still applies when an area is set
  add constraint libraries_district_in_state foreign key (district_id, state_id) references public.districts (id, state_id),
  add constraint libraries_city_in_district  foreign key (city_id, district_id) references public.city_districts (city_id, district_id);
create index libraries_place_idx on public.libraries (state_id, district_id, city_id);

-- ---------------------------------------------------------------- who may read and write
alter table public.states         enable row level security;
alter table public.districts      enable row level security;
alter table public.city_districts enable row level security;

grant select on public.states, public.districts, public.city_districts to anon, authenticated;
create policy states_select on public.states for select to anon, authenticated using (true);
create policy districts_select on public.districts for select to anon, authenticated using (true);
create policy city_districts_select on public.city_districts for select to anon, authenticated using (true);

-- Owners pick the state and district of their library like the city and area.
grant insert (state_id, district_id) on public.libraries to authenticated;
grant update (state_id, district_id) on public.libraries to authenticated;

-- A town needs a district link, so an admin adds towns only through admin_add_city (below). Switching one off stays direct.
revoke insert on public.cities from authenticated;

-- ---------------------------------------------------------------- admin: add a missing town
create function public.admin_add_city(p_district uuid, p_name text)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  clean text := btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'));
  st uuid;
  new_id uuid;
begin
  perform public.require_admin();
  if clean = '' then
    raise exception 'Enter a town name.' using errcode = 'invalid_parameter_value';
  end if;
  select state_id into st from public.districts where id = p_district;
  if not found then
    raise exception 'District not found.' using errcode = 'no_data_found';
  end if;
  if exists (select 1 from public.cities where state_id = st and lower(name) = lower(clean)) then
    raise exception '% is already listed in this state. Add the district to the name, for example "% (District)".', clean, clean
      using errcode = 'unique_violation';
  end if;
  return new_id;
end;
$$;

-- ---------------------------------------------------------------- create a library (replaces 0007)
create or replace function public.create_library(p_input jsonb, p_shifts jsonb)
returns uuid
language plpgsql security definer set search_path = public
as $$
declare
  new_id uuid;
  s jsonb;
  shift_count integer;
begin
  if auth.uid() is null then
    raise exception 'Sign in first.' using errcode = 'insufficient_privilege';
  end if;
  if public.current_user_role() is distinct from 'owner' then
    raise exception 'Only owners can list a library.' using errcode = 'insufficient_privilege';
  end if;
  shift_count := coalesce(jsonb_array_length(p_shifts), 0);
  if shift_count < 1 or shift_count > 3 then
    raise exception 'Set up between 1 and 3 shifts.' using errcode = 'invalid_parameter_value';
  end if;

  begin
    values (
      auth.uid(),
      btrim(p_input ->> 'name'),
      (p_input ->> 'state_id')::uuid,
      (p_input ->> 'district_id')::uuid,
      (p_input ->> 'city_id')::uuid,
      nullif(p_input ->> 'area_id', '')::uuid,
      btrim(p_input ->> 'address'),
      coalesce(btrim(p_input ->> 'landmark'), ''),
      btrim(p_input ->> 'pincode'),
      btrim(p_input ->> 'phone'),
      (p_input ->> 'capacity')::integer,
      coalesce(btrim(p_input ->> 'timings'), ''),
      array(select jsonb_array_elements_text(coalesce(p_input -> 'amenities', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(p_input -> 'photos', '[]'::jsonb)))
    )
    returning id into new_id;
  exception
    when unique_violation then
      raise exception 'You already have a library.' using errcode = 'unique_violation';
    when foreign_key_violation then
      raise exception 'Pick the district from the chosen state, the city from that district, and an area from that city.'
        using errcode = 'invalid_parameter_value';
    when check_violation or not_null_violation then
      raise exception 'Check the library details: state, district, city, name, address, a 6-digit pincode, a 10-digit phone and 1 to 500 seats.'
        using errcode = 'invalid_parameter_value';
  end;

  for s in select * from jsonb_array_elements(p_shifts) loop
    values (new_id, btrim(s ->> 'name'), (s ->> 'start_time')::time, (s ->> 'end_time')::time, (s ->> 'monthly_fee_paise')::integer);
  end loop;

  return new_id;
end;
$$;

-- ---------------------------------------------------------------- public search (replaces 0004): filter by state and district too
drop function public.public_library(uuid);
drop function public.public_libraries(uuid, uuid, integer, text[]);

create function public.public_libraries(
  p_state uuid default null,
  p_district uuid default null,
  p_city uuid default null,
  p_area uuid default null,
  p_max_fee_paise integer default null,
  p_amenities text[] default null
)
returns table (
  id uuid, name text,
  state_id uuid, state_name text, district_id uuid, district_name text,
  city_id uuid, city_name text, area_id uuid, area_name text,
  address text, pincode text, landmark text, phone text, timings text,
  amenities text[], photos text[], from_fee_paise integer, total_seats integer, shifts jsonb
)
language sql stable security definer set search_path = public
as $$
  select
    l.id, l.name,
    l.state_id, st.name, l.district_id, d.name,
    l.city_id, c.name, l.area_id, coalesce(a.name, ''),
    l.address, l.pincode, l.landmark, l.phone, l.timings,
    l.amenities, l.photos,
    (select min(sh.monthly_fee_paise) from public.shifts sh where sh.library_id = l.id and sh.is_active),
    (select count(*)::integer from public.seats s where s.library_id = l.id and s.is_active),
    coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', sh.id, 'name', sh.name,
               'start_time', to_char(sh.start_time, 'HH24:MI'), 'end_time', to_char(sh.end_time, 'HH24:MI'),
               'monthly_fee_paise', sh.monthly_fee_paise,
               'total_seats', (select count(*) from public.seats s where s.library_id = l.id and s.is_active),
               'seats_left', (select count(*) from public.seats s
                               where s.library_id = l.id and s.is_active
                                 and not exists (select 1 from public.members m
                                                  where m.seat_id = s.id and m.shift_id = sh.id and m.status = 'active'))
             ) order by sh.start_time)
        from public.shifts sh where sh.library_id = l.id and sh.is_active
    ), '[]'::jsonb)
  from public.libraries l
  join public.states st on st.id = l.state_id
  join public.districts d on d.id = l.district_id
  join public.cities c on c.id = l.city_id and c.is_active
  left join public.areas a on a.id = l.area_id
  where public.is_library_active(l.id)
    and (l.area_id is null or a.is_active)          -- a switched-off area still hides its libraries, as before
    and (p_state is null or l.state_id = p_state)
    and (p_district is null or l.district_id = p_district)
    and (p_city is null or l.city_id = p_city)
    and (p_area is null or l.area_id = p_area)
    and (p_max_fee_paise is null or exists (
          select 1 from public.shifts sh where sh.library_id = l.id and sh.is_active and sh.monthly_fee_paise <= p_max_fee_paise))
    and (p_amenities is null or cardinality(p_amenities) = 0 or l.amenities @> p_amenities)
$$;

create function public.public_library(p_id uuid)
returns table (
  id uuid, name text,
  state_id uuid, state_name text, district_id uuid, district_name text,
  city_id uuid, city_name text, area_id uuid, area_name text,
  address text, pincode text, landmark text, phone text, timings text,
  amenities text[], photos text[], from_fee_paise integer, total_seats integer, shifts jsonb
)
language sql stable security definer set search_path = public
as $$ select * from public.public_libraries() p where p.id = p_id $$;

-- ---------------------------------------------------------------- what a student sees (replaces 0005): area may be empty
drop function public.my_seat_requests();
create function public.my_seat_requests()
returns table (
  id uuid, library_id uuid, library_name text, area_name text, city_name text,
  shift_id uuid, shift_name text, start_time text, end_time text,
  status text, created_at timestamptz, decided_at timestamptz,
  state_id uuid, district_id uuid, city_id uuid
)
language sql stable security definer set search_path = public
as $$
  select r.id, r.library_id, l.name, coalesce(a.name, ''), c.name,
         r.shift_id, sh.name, to_char(sh.start_time, 'HH24:MI'), to_char(sh.end_time, 'HH24:MI'),
         r.status, r.created_at, r.decided_at,
         l.state_id, l.district_id, l.city_id
  from public.seat_requests r
  join public.libraries l on l.id = r.library_id
  left join public.areas a on a.id = l.area_id
  join public.cities c on c.id = l.city_id
  join public.shifts sh on sh.id = r.shift_id
  where r.student_id = auth.uid()
  order by r.created_at desc
$$;

create or replace function public.my_memberships()
returns jsonb
language sql stable security definer set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'member_id', m.id,
    'library_id', l.id, 'library_name', l.name, 'library_phone', l.phone,
    'area_name', coalesce(a.name, ''), 'city_name', c.name, 'district_name', d.name, 'state_name', st.name,
    'address', l.address,
    'shift_id', sh.id, 'shift_name', sh.name,
    'start_time', to_char(sh.start_time, 'HH24:MI'), 'end_time', to_char(sh.end_time, 'HH24:MI'),
    'seat_number', s.seat_number,
    'start_date', m.start_date, 'expiry_date', m.expiry_date,
    'payments', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', f.id, 'amount_paise', f.amount_paise, 'paid_on', f.paid_on,
               'mode', f.mode, 'is_void', f.is_void, 'void_reason', f.void_reason) order by f.paid_on desc)
        from public.fee_payments f where f.member_id = m.id), '[]'::jsonb)
  ) order by l.name, sh.start_time), '[]'::jsonb)
  from public.members m
  join public.libraries l on l.id = m.library_id
  left join public.areas a on a.id = l.area_id
  join public.cities c on c.id = l.city_id
  join public.districts d on d.id = l.district_id
  join public.states st on st.id = l.state_id
  join public.shifts sh on sh.id = m.shift_id
  left join public.seats s on s.id = m.seat_id
  where m.student_id = auth.uid() and m.status = 'active'
$$;

-- ---------------------------------------------------------------- who may call what
revoke all on function
  public.admin_add_city(uuid, text),
  public.public_libraries(uuid, uuid, uuid, uuid, integer, text[]), public.public_library(uuid),
  public.my_seat_requests()
from public, anon, authenticated;

grant execute on function public.admin_add_city(uuid, text), public.my_seat_requests() to authenticated;
grant execute on function public.public_libraries(uuid, uuid, uuid, uuid, integer, text[]), public.public_library(uuid)
to anon, authenticated;
